// Instance A provisioned host of an InstanceGroup or of a Cluster. An instance is a
// server held by a reservation: it is materialized automatically when its owner
// reserves the host, and there is no way to create one directly.
//
// Exactly one owner, always. A group-owned instance publishes
// `instanceGroupUuid`/`instanceGroupId`; a cluster-owned one publishes
// `clusterUuid`/`clusterId`. Branch on which pair is PRESENT — neither pair is
// `required`, and the absent one is omitted rather than empty.
//
// Identity and ownership are stored by the compute service; everything about the
// host itself lives in the infrastructure service and is read on every request
// rather than duplicated here. An Instance IS a host, so
// that read is not an enrichment: when the infrastructure service cannot be
// reached the request fails with `503` instead of returning a stored skeleton.
type Instance struct {
	// ClusterId Id of the owning Cluster — what `GET .../compute/clusters/{id}` is keyed
	// by, so the cluster can be fetched straight from this instance. This is the
	// cluster's `id` as that resource publishes it; the service's internal
	// primary key is a different value and never appears here. Read from the
	// cluster on every request rather than stored, so the two can never
	// disagree. Absent when the instance belongs to an instance group instead.
	ClusterId *string `json:"clusterId,omitempty"`

	// ClusterUuid Uid of the owning Cluster; the value the list endpoint's `clusterUuid`
	// filter takes. Absent when the instance belongs to an instance group
	// instead.
	ClusterUuid *openapi_types.UUID `json:"clusterUuid,omitempty"`
	CreatedAt   *time.Time          `json:"createdAt,omitempty"`

	// DeletedAt When this instance was deleted. Present ONLY on a tombstone, which is only returned when the request asked with `showDeleted=true` — so its presence identifies a deleted instance without parsing `state`.
	DeletedAt *time.Time `json:"deletedAt,omitempty"`

	// Execution The most recent operation requested on this instance through this API, and how it ended — the one question the live host cannot answer. A deprovision and an operator-driven cleaning reach the server identically, and the server's own failure reason is cleared when a retry re-arms it, so this is the only durable record that the REQUEST succeeded or failed. Absent when none has ever been requested.
	// Independent of `state`: `state` is what the host IS right now, read live from the reservation; this is what was ASKED FOR and what became of it.
	Execution *struct {
		// CompletedAt When the operation reached a terminal state. Absent while it is still in flight, which is what distinguishes a running operation from a finished one without consulting the workflow.
		CompletedAt *time.Time `json:"completedAt,omitempty"`

		// Error Why the operation did not succeed. Absent on success and while in flight — so `completedAt` present with no `error` is the only shape that means the operation succeeded.
		//
		// A STABLE sentence chosen by the terminal the operation reached, not a passthrough of the underlying failure. Quote `execution.id` to an operator for the specific cause. Do not parse this field.
		Error *string `json:"error,omitempty"`

		// Id Identifier of the execution, for correlation with the operation's workflow.
		Id string `json:"id"`

		// RequestedAt When the operation was accepted.
		RequestedAt time.Time `json:"requestedAt"`

		// Type The operation this execution performs.
		Type InstanceExecutionType `json:"type"`
	} `json:"execution,omitempty"`

	// Health Canonical host health as infrastructure observes it, with `reason`
	// carrying the explanation. Observability-only: it never drives
	// `state`. `unknown` means never observed, or the last
	// observation has gone stale.
	Health *Health `json:"health,omitempty"`

	// Hostname The host's effective hostname, as the infrastructure service reports it right now. Not stored by this service — a captured copy would only be a second value to go stale. Usually the same as `serverSlug`, but automation may suffix it.
	Hostname *string `json:"hostname,omitempty"`

	// Id Server-generated identifier, and the value every path and filter takes.
	//
	// The same identity as `uid`, spelled the way every other resource in this
	// API spells an `id`: the `inst-` prefix followed by `uid` without its
	// hyphens. It is not a second identifier, so there is nothing that could
	// disagree between the two, and a client may treat either as canonical.
	//
	// Stable for the lifetime of the host's membership in its owner: it is
	// derived from an identity minted by this service, not by the infrastructure
	// provider, so it survives the provider's own instance being destroyed and
	// re-created (as a deprovision followed by a re-provision does).
	Id *string `json:"id,omitempty"`

	// InstanceGroupId Id (slug) of the owning InstanceGroup — what
	// `GET .../compute/instance-groups/{id}` is keyed by, so the group can be
	// fetched straight from this instance. Read from the group on every request
	// rather than stored here, so the two can never disagree. Absent when the
	// instance belongs to a cluster instead.
	InstanceGroupId *string `json:"instanceGroupId,omitempty"`

	// InstanceGroupUuid Uid of the owning InstanceGroup; the value the list endpoint's
	// `instanceGroupUuid` filter takes. Absent when the instance belongs to a
	// cluster instead.
	InstanceGroupUuid *openapi_types.UUID `json:"instanceGroupUuid,omitempty"`

	// Inventory Hardware the host actually has, from its latest infrastructure inventory snapshot. An empty object when none has been collected.
	Inventory *HardwareSpecs `json:"inventory,omitempty"`

	// LastPowerActionError Explains why the most recent power operation on this instance's server is known to have failed (NICo refused it, was unreachable after retries, or the workflow itself failed). That operation is any power action or BMC reset (`resetBmc`) against the server this instance occupies, whether requested on this instance or by an operator on the server directly — all are recorded here. Absent when no failure is known for the current/most recent operation — a success is never distinguished from "not yet known" here. Independent of `state` — a failed power operation does not mean this instance itself is unhealthy.
	LastPowerActionError *string `json:"lastPowerActionError,omitempty"`

	// NetworkConfiguration The host's runtime network interfaces, as the infrastructure service reports them right now. Not stored by this service.
	NetworkConfiguration *[]NetworkInterfaceConfig `json:"networkConfiguration,omitempty"`

	// NodePool Id (slug) of the owner's node pool this host was provisioned into — the name it carries in that owner's `nodePools`. A pool has no route of its own.
	NodePool *string `json:"nodePool,omitempty"`

	// NodePoolUuid Uid of the owner's node pool this host was provisioned into; the value the list endpoint's `nodePoolUuid` filter takes.
	NodePoolUuid *openapi_types.UUID `json:"nodePoolUuid,omitempty"`

	// ReservationUuid Infrastructure reservation holding this server, or absent when none is recorded.
	ReservationUuid *openapi_types.UUID `json:"reservationUuid,omitempty"`

	// SelfLink Server-defined URL for this resource.
	SelfLink *string `json:"selfLink,omitempty"`

	// ServerSlug The host's name as registered in the infrastructure service. This is what identifies it across the service boundary.
	ServerSlug *string `json:"serverSlug,omitempty"`

	// State The instance's lifecycle state, and the only state this resource reports.
	// The vocabulary is the platform's, so the same value means the same thing
	// here as on any other resource that reports one.
	//
	// Derived on every request from the host the infrastructure service reports
	// — never from a stored copy, which is exactly the value that goes stale.
	// The host's own finer-grained state is NOT published alongside it: two
	// lifecycle vocabularies on one object would leave a caller to reconcile
	// them by hand. Where one value covers more than one host state,
	// `stateMessage` names the step in words.
	//
	// The lifecycle in order: `not_provisioned` (the server is held for this
	// instance and nothing has been provisioned onto it — allocated and idle,
	// with nothing asked of it), `provisioning` (provisioning has been accepted
	// or is under way), `running`, then on teardown `deprovisioning` (the
	// instance is being wiped off the host) and `deleting` (the host itself is
	// on its way back). `degraded` is reachable from anywhere.
	//
	// `state` is read live from the infrastructure service — from the host and
	// from the reservation holding it. An operation this API has accepted but
	// not yet pushed there is not visible here: a host whose deprovision was
	// accepted a moment ago is still running, and that is what it reports. Two
	// other fields carry the acceptance — `execution`, which appears on this
	// instance with `requestedAt` set and no `completedAt`, and the owning
	// instance group's own `updating` state. Both are committed before the
	// request is answered.
	//
	//
	// Once the infrastructure service has the request, `state` moves: a host
	// targeted at `reserved` reports `deprovisioning` before anything has
	// touched the machine, and one targeted at `provisioned` reports
	// `provisioning`.
	//
	//
	// `deleting` covers the IDLE windows of a teardown — from the point its
	// group's reservation starts being released until the host's wipe begins,
	// and again from the wipe finishing until the host itself is handed back.
	// A host actively being wiped reports `deprovisioning` throughout, including
	// during a group delete: the wipe and the hand-back are separately
	// observable and take very different amounts of time. Without the
	// reservation those idle windows would report a settled state identical to a
	// finished deprovision's, which would tell a tenant mid-teardown that their
	// instance is allocated and idle. Before the release begins, a
	// still-provisioned host reports `running`.
	// `stateMessage` distinguishes accepted-but-not-started from in-progress.
	//
	// `deleted` is the terminal state, and it is only ever returned when the
	// caller asked for tombstones with `showDeleted=true`. A default read stops
	// seeing the instance the moment it is deleted: the listing omits it and the
	// single GET answers `410 Gone` — gone rather than not-found, because the id
	// named a real instance of this project and ids are never reused.
	//
	// A `deleted` instance carries no host DATA, and nothing is read from the
	// infrastructure service for it. That is deliberate: the server was released
	// and may now be held by another project, so a live read would report the
	// current state of a machine that is no longer this tenant's.
	//
	// What it does carry is the stored record — identity, the owner and pool it
	// belonged to, `serverSlug`, timestamps. `serverSlug` is published because it
	// is a stored record of which machine this instance used to occupy, not a
	// fact about that machine today.
	//
	// The host-derived fields are still PRESENT, in their empty form:
	// `networkConfiguration` is `[]`, `health.state` is `unknown`, and
	// `inventory` is `{}`. They are never populated for a tombstone, so branch
	// on `state` or on `deletedAt` rather than on whether a key is present.
	//
	// `degraded` means THE HOST REPORTED A PROBLEM — its last transition
	// failed, or it is paused or awaiting operator input. It is derived from the
	// host's lifecycle alone and never from `health`: a host reporting
	// `health.state: unhealthy` while provisioned is `running` here and says so
	// in `health`. The two are deliberately separate judgements.
	//
	// An instance whose host cannot be ATTRIBUTED to it — unknown to the
	// infrastructure service, held by a different reservation, or with no
	// reservation recorded — is `unknown`, not `degraded`. Nothing is impaired
	// in that case; the machine may be fine and simply not this instance's, so
	// the honest answer is that its state could not be determined. Keeping the
	// two apart is also what makes `degraded` answerable by a filter.
	//
	// `stopping` and `stopped` are part of the vocabulary but are not reachable
	// yet: nothing models machine power, so no host state produces them. They
	// become reachable when power operations land.
	//
	// `unknown` means the state could not be determined — the host reported
	// nothing nameable, the infrastructure service has widened its vocabulary
	// ahead of this one, the host reported a state from outside this instance's
	// lifetime (before it was provisioned onto, or after it was released), or
	// the host could not be attributed to this instance at all. `stateMessage`
	// says which.
	State *InstanceState `json:"state,omitempty"`

	// StateMessage Why the instance is in the `state` it reports. Present for every state except `running`, which needs none.
	//
	// This is also where the host's finer-grained step is reported. Where one `state` covers more than one underlying step — `provisioning` covers being provisioned and being recovered after a failure, `degraded` covers failed, paused and awaiting-operator — this sentence is what tells them apart.
	//
	// A STABLE, self-contained sentence, never a passthrough of the underlying failure: the infrastructure service builds its own error text from raw internal errors, which can carry service endpoints, driver output and workflow identifiers. That text is recorded against the host there and logged by this service against the instance; an operator has both. Do not parse this field — branch on `state` instead.
	StateMessage *string `json:"stateMessage,omitempty"`

	// Uid The same identity as `id`, in canonical UUID form. Published because the
	// platform convention pairs a slug `id` with a UUID `uid`; both spell the
	// one value this instance is keyed by.
	Uid *openapi_types.UUID `json:"uid,omitempty"`
}

