// SecurityGroupRule One filter rule in a `SecurityGroup`'s nested `rules.ingress` or
// `rules.egress` list. Direction is implied by which list the rule sits in —
// there is no `direction` field on the rule itself. A rule matches traffic for
// one `protocol` between two CIDR prefixes, optionally narrowed to port ranges,
// and either permits or denies it.
//
// Rules are stateless by default: return traffic must be permitted explicitly
// with a matching rule in the opposite direction list.
//
// **One automatic exception.** On the `nico` fabric the platform enables
// `statefulEgress`, which makes an EGRESS rule stateful when it names a
// `protocol` and a `destinationPortRange` but NO `sourcePortRange`. Return
// traffic for the flows such a rule permits is allowed back without a matching
// ingress rule. The qualifying shape is therefore narrow — an egress `tcp` or
// `udp` rule with a destination port and an unpinned source port, which is the
// ordinary way a client-side rule is written. Everything else stays stateless:
// every ingress rule, every egress rule that pins `sourcePortRange`, and every
// rule on `icmp`, `icmp6` or `any`, since those cannot carry ports at all.
//
// There is no field for this on the rule and none on the group — it is a
// property of the enforcement, not of the declaration, and it is not reported
// back per rule.
//
// A rule is not an addressable resource: it has no id of its own and there is
// no rules subresource. The group's `rules` object is the desired state and is
// replaced wholesale on update, which keeps "what does this group allow" a
// single read of a single object.
//
// Within a direction list, evaluation is first-match in list order (see
// `SecurityGroupRules`). There is no per-rule priority field — position in the
// array is the only ordering signal.
//
// There is no remote-security-group reference in this model — a rule always
// names two literal prefixes. Both are required: a rule that constrains only
// one side is written by sending the wide-open prefix (`0.0.0.0/0` or `::/0`)
// on the other, so the intent is always visible in the rule rather than
// implied by an omission.
type SecurityGroupRule struct {
	// Action What to do with traffic this rule matches. `permit` allows it, `deny`
	// drops it. Lowercase on the wire; an uppercase spelling is rejected with
	// `422` and `details[].reason: INVALID_ARGUMENT` rather than normalized.
	Action SecurityGroupRuleAction `json:"action"`

	// DestinationPortRange Destination ports the rule matches, as a single port (`"80"`) or an
	// inclusive range (`"80-81"`). Same string wire format, same bounds and
	// the same protocol restriction as `sourcePortRange`: valid only for `tcp`
	// and `udp`, rejected with `422` on `icmp`, `icmp6` and `any`.
	//
	// Omit it to match any destination port.
	DestinationPortRange *string `json:"destinationPortRange,omitempty"`

	// DestinationPrefix Destination address range the rule matches, as an IPv4 or IPv6 prefix in
	// CIDR notation. Required, and validated exactly as `sourcePrefix` is:
	// host bits must be zero. Use `0.0.0.0/0` or `::/0` to match any
	// destination.
	DestinationPrefix string `json:"destinationPrefix"`

	// Name Optional human-friendly label for this rule. Free text, not unique, and
	// not used for lookup or for ordering. List position within
	// `rules.ingress` / `rules.egress` is the only ordering signal (first-match
	// evaluation). It exists so a rule set stays readable when it grows past
	// the point where the prefixes alone explain the intent.
	Name *string `json:"name,omitempty"`

	// Protocol IP protocol the rule matches. `any` matches every protocol and is the
	// way to express a blanket permit or deny. `icmp6` is the IPv6 spelling
	// and is distinct from `icmp` — a rule written for one does not match the
	// other.
	//
	// Only `tcp` and `udp` are port-bearing. `sourcePortRange` and
	// `destinationPortRange` are rejected on `icmp`, `icmp6` and `any` with
	// `422` and `details[].reason: INVALID_ARGUMENT`, rather than being
	// accepted and ignored: a rule that reads as port-scoped but is not would
	// be a security surprise.
	//
	// Lowercase on the wire; an uppercase spelling is rejected with `422` and
	// `details[].reason: INVALID_ARGUMENT` rather than normalized.
	Protocol SecurityGroupRuleProtocol `json:"protocol"`

	// SourcePortRange Source ports the rule matches, as a single port (`"80"`) or an inclusive
	// range (`"80-81"`). A string, not an integer or an object, on both read
	// and write — a single port is `"80"` and never `80`.
	//
	// Optional; omit it to match any source port. Valid only when `protocol`
	// is `tcp` or `udp`: supplying it alongside `icmp`, `icmp6` or `any` is
	// rejected with `422` and `details[].reason: INVALID_ARGUMENT`.
	//
	// Each bound must be between `0` and `65535`, and the low bound must not
	// exceed the high bound. `"80-80"` is accepted and is equivalent to
	// `"80"`; the platform reports the normalized spelling it stored.
	SourcePortRange *string `json:"sourcePortRange,omitempty"`

	// SourcePrefix Source address range the rule matches, as an IPv4 or IPv6 prefix in CIDR
	// notation. Required. Use `0.0.0.0/0` or `::/0` to match any source.
	//
	// The host bits must be zero: `192.168.1.0/24` is accepted and
	// `192.168.1.1/24` is rejected with `422` and
	// `details[].reason: INVALID_ARGUMENT` rather than silently normalized to
	// the network address, because that spelling is far more often a typo than
	// an intent. The address family is not required to match
	// `destinationPrefix` at the schema level, but a rule that mixes families
	// matches nothing.
	SourcePrefix string `json:"sourcePrefix"`
}

// SecurityGroupRuleAction What to do with traffic this rule matches. `permit` allows it, `deny`
// drops it. Lowercase on the wire; an uppercase spelling is rejected with
// `422` and `details[].reason: INVALID_ARGUMENT` rather than normalized.
type SecurityGroupRuleAction string

// SecurityGroupRuleProtocol IP protocol the rule matches. `any` matches every protocol and is the
// way to express a blanket permit or deny. `icmp6` is the IPv6 spelling
// and is distinct from `icmp` — a rule written for one does not match the
// other.
//
// Only `tcp` and `udp` are port-bearing. `sourcePortRange` and
// `destinationPortRange` are rejected on `icmp`, `icmp6` and `any` with
// `422` and `details[].reason: INVALID_ARGUMENT`, rather than being
// accepted and ignored: a rule that reads as port-scoped but is not would
// be a security surprise.
//
// Lowercase on the wire; an uppercase spelling is rejected with `422` and
// `details[].reason: INVALID_ARGUMENT` rather than normalized.
type SecurityGroupRuleProtocol string

// SecurityGroupRules Nested ingress and egress rule lists for a `SecurityGroup`. Direction is
// implied by which list a rule sits in — there is no `direction` field on
// individual rules.
//
// Both lists are always present on read (possibly empty). On write, omit a
// list or send an empty array to leave that direction with no rules. There is
// no rule resource to create or delete separately, and an update replaces the
// whole `rules` object wholesale rather than patching entries.
//
// Evaluation within each list is **first-match in list order**: the platform
// walks `ingress` (or `egress`) from index 0 and applies the action of the
// first rule that matches the packet. Later overlapping rules do not override
// earlier ones. A broad `deny` of `0.0.0.0/0` before a narrower `permit` for
// one port therefore denies that port; put the narrower `permit` first if it
// should win. Order is preserved end-to-end (API → database list position →
// UFO CRD arrays). The two directions are independent — ingress and egress
// never compete with each other.
//
// **A group carries at most 256 rules in total**, counted as
// `ingress.length + egress.length` — the same number reported as
// `SecurityGroup.ruleCount`. The budget is shared between the two directions
// rather than allotted per direction, so a group may hold 256 ingress rules
// and no egress rules, or any split summing to 256. A create or update over
// the limit is rejected with `422` naming the total and both list lengths.
//
// The limit is deliberately NOT declared as a schema constraint, for two
// reasons. A per-list `maxItems` would be necessary but not sufficient — two
// lists of 200 each satisfy it and are still rejected on their sum of 400 — so
// it could not replace the server-side check. And this schema is shared by the
// read model: a group created before the limit existed may hold more, and a
// numeric bound here would make every read of that group fail strict client
// validation instead of reporting what it actually holds. The limit binds
// writes; reads stay honest.
//
// The limit is on the group, but the pressure comes from where groups end up.
// The rules that filter one network interface are those of every group
// attached to its cluster (or instance group) *plus* those of every group
// attached to the VPC it connects to — at most 16 groups from each binding.
// The per-group limit is what keeps that combined set within the fabric's own
// ceiling on rules per interface.
type SecurityGroupRules struct {
	// Egress Ordered rules that filter traffic leaving the instance. First-match in
	// list order within this array. An empty list is legal and matches nothing
	// on the egress side.
	//
	// No `maxItems` is declared; the limit is the 256-rule total across both
	// lists, enforced on write. See the schema description above.
	Egress []SecurityGroupRule `json:"egress"`

	// Ingress Ordered rules that filter traffic arriving at the instance. First-match
	// in list order within this array. An empty list is legal and matches
	// nothing on the ingress side.
	//
	// No `maxItems` is declared; the limit is the 256-rule total across both
	// lists, enforced on write. See the schema description above.
	Ingress []SecurityGroupRule `json:"ingress"`
}

